//! Integration tests for point data grids and their file I/O.
//!
//! The files in tests/data/points were written by C++ OpenVDB 10.0.1 with
//! tests/data/cpp/points_ref.cpp; `<name>.dump.txt` holds `points_ref dump <name>.vdb`. The
//! attribute values are generated by formulas mirrored below.

mod common;

use common::*;
use std::fmt::Write as _;
use std::path::Path;
use vdb::io::{self, Compression, File, WriteOptions};
use vdb::math::{Transform, Vec3d, Vec3f};
use vdb::metadata::{MetaMap, MetaValue};
use vdb::points::{self, *};
use vdb::AnyGrid;

const REFERENCE_FILES: &[&str] =
    &["points_attrs", "points_none", "points_zip", "points_codecs", "points_misc", "points_scatter"];
const N: usize = 40;
const NAMES: [&str; 4] = ["alpha", "beta", "", "gamma"];

fn ref_path(name: &str) -> std::path::PathBuf {
    data("points").join(format!("{}.vdb", name))
}

/// The generator's position formula (`position(i)` in points_ref.cpp).
fn position(i: usize) -> Vec3f {
    let i = i as i32;
    Vec3f::new(
        ((i * 7) % 13) as f32 * 0.31 + 0.5,
        ((i * 5) % 11) as f32 * 0.27 + 0.5,
        ((i * 3) % 7) as f32 * 0.45 - 1.5,
    )
}

fn hex(v: u64) -> String {
    format!("{:016x}", v)
}

fn fnv(data: &[u8], mut h: u64) -> u64 {
    for b in data {
        h ^= *b as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}
const FNV_INIT: u64 = 0xcbf29ce484222325;

/// Canonical description of a point data grid, identical to `points_ref dump`.
fn dump_point_grid(out: &mut String, name: &str, grid: &PointDataGrid) {
    writeln!(out, "grid {}", name).unwrap();
    let m = grid.transform().map().affine_matrix();
    out.push_str("  transform");
    for v in m.0.iter().flatten() {
        write!(out, " {}", hex(v.to_bits())).unwrap();
    }
    out.push('\n');
    let tree = grid.tree();
    writeln!(out, "  leaf_count {}", tree.leaf_count()).unwrap();
    writeln!(out, "  active_voxels {}", tree.active_voxel_count()).unwrap();
    writeln!(out, "  points {}", point_count(tree)).unwrap();
    let Some(first) = tree.leaves().next() else { return };
    let d = first.attributes.descriptor();
    for (i, name) in d.names().iter().enumerate() {
        let t = d.attribute_type(i);
        writeln!(out, "  attribute {} {} {} {}", i, name, t.value_type, t.codec).unwrap();
    }
    for (g, o) in d.group_map() {
        writeln!(out, "  group {} {}", g, o).unwrap();
    }
    dump_meta(out, d.metadata(), "  descriptor_");
    for leaf in tree.leaves() {
        let o = leaf.origin();
        let mut mask_hash = FNV_INIT;
        for w in leaf.leaf.value_mask().words() {
            mask_hash = fnv(&w.to_le_bytes(), mask_hash);
        }
        let mut offset_hash = FNV_INIT;
        for v in leaf.leaf.buffer() {
            offset_hash = fnv(&v.to_le_bytes(), offset_hash);
        }
        writeln!(
            out,
            "  leaf {} {} {} points {} mask {} offsets {}",
            o[0],
            o[1],
            o[2],
            leaf.point_count(),
            hex(mask_hash),
            hex(offset_hash)
        )
        .unwrap();
        for (i, a) in leaf.attributes.arrays().enumerate() {
            writeln!(
                out,
                "    array {} size {} stride {} data_size {} flags {} uniform {} storage {}",
                i,
                a.size(),
                a.stride(),
                a.data_size(),
                a.flags(),
                a.is_uniform() as u8,
                hex(fnv(a.storage(), FNV_INIT))
            )
            .unwrap();
        }
    }
}

/// Canonical description of the point data grids of a file, as `points_ref dump` prints it.
fn dump_points_file(path: &Path) -> String {
    let file = File::open(path).unwrap();
    let mut grids: Vec<(String, AnyGrid)> =
        file.read_grids().unwrap().into_iter().map(|g| (g.name().to_string(), g)).collect();
    if file.header().has_grid_offsets {
        grids.sort_by(|a, b| a.0.cmp(&b.0));
    }
    let mut out = String::new();
    for (name, g) in &grids {
        if let Some(p) = g.as_point_data() {
            dump_point_grid(&mut out, name, p);
        }
    }
    out
}

fn assert_same_dump(actual: &str, expected: &str, what: &str) {
    if actual == expected {
        return;
    }
    for (i, (a, e)) in actual.lines().zip(expected.lines()).enumerate() {
        if a != e {
            panic!("{}: first difference at line {}:\n  actual:   {}\n  expected: {}", what, i + 1, a, e);
        }
    }
    panic!("{}: dumps differ in length ({} vs {} lines)", what, actual.lines().count(), expected.lines().count());
}

fn read_points(name: &str, grid: &str) -> PointDataGrid {
    io::read_grid(ref_path(name), grid).unwrap().into_point_data().unwrap()
}

/// Map each point (by its `id` attribute) to (world position, leaf view index, point index).
struct PointRecord {
    pos: Vec3d,
    density: f32,
    v: Vec3f,
    name: String,
    arr: [f32; 3],
    even: bool,
    first: bool,
}

fn records(grid: &PointDataGrid) -> Vec<Option<PointRecord>> {
    let mut out: Vec<Option<PointRecord>> = (0..N).map(|_| None).collect();
    for leaf in grid.tree().leaves() {
        let p = leaf.attribute_handle::<Vec3f>("P").unwrap();
        let id = leaf.attribute_handle::<i32>("id").unwrap();
        let density = leaf.attribute_handle::<f32>("density").unwrap();
        let v = leaf.attribute_handle::<Vec3f>("v").unwrap();
        let arr = leaf.attribute_handle::<f32>("arr").unwrap();
        let names =
            StringAttributeHandle::new(leaf.attribute_array("name").unwrap(), leaf.attributes.descriptor().metadata())
                .unwrap();
        let even = leaf.group_handle_by_name("even").unwrap();
        let first = leaf.group_handle_by_name("first").unwrap();
        for (ijk, i) in leaf.index_all().with_coords() {
            let k = (id.get(i) - 100) as usize;
            let q = p.get(i);
            out[k] = Some(PointRecord {
                pos: grid
                    .transform()
                    .index_to_world(ijk.as_vec3d() + Vec3d::new(q[0] as f64, q[1] as f64, q[2] as f64)),
                density: density.get(i),
                v: v.get(i),
                name: names.get(i).unwrap(),
                arr: [arr.get_strided(i, 0), arr.get_strided(i, 1), arr.get_strided(i, 2)],
                even: even.get(i),
                first: first.get(i),
            });
        }
    }
    out
}

// ---------------------------------------------------------------------------
// Reading C++-written files

/// Every reference file reads back exactly as the C++ library sees it (offsets, masks,
/// descriptors and the raw storage of every attribute array).
#[test]
fn reference_dumps_match_cpp() {
    for name in REFERENCE_FILES {
        let expected = std::fs::read_to_string(data("points").join(format!("{}.dump.txt", name))).unwrap();
        assert_same_dump(&dump_points_file(&ref_path(name)), &expected, name);
    }
}

#[test]
fn attribute_values_from_cpp() {
    for file in ["points_attrs", "points_none", "points_zip"] {
        let grid = read_points(file, "attrs");
        assert_eq!(point_count(grid.tree()), N as u64);
        let d = grid.tree().descriptor().unwrap();
        assert_eq!(d.names(), vec!["P", "density", "v", "id", "name", "arr", "uni", "hid", "__group"]);
        assert_eq!(d.default_value("uni"), Some(&MetaValue::Float(1.0)));
        assert!(d.has_group("unused"));
        let tol = if file == "points_zip" { 0.25 / 65535.0 + 1e-6 } else { 1e-6 };
        for (k, r) in records(&grid).into_iter().enumerate() {
            let r = r.unwrap_or_else(|| panic!("{}: point {} missing", file, k));
            let p = position(k);
            assert!((r.pos - Vec3d::new(p[0] as f64, p[1] as f64, p[2] as f64)).abs().max_component() < tol);
            assert_eq!(r.density, k as f32 * 0.5);
            assert_eq!(r.v, Vec3f::new(k as f32, -(k as f32), 0.5 * k as f32));
            assert_eq!(r.name, NAMES[k % 4]);
            assert_eq!(r.arr, [k as f32, k as f32 + 0.25, k as f32 + 0.5]);
            assert_eq!(r.even, k % 2 == 0);
            assert_eq!(r.first, k < 5);
        }
        for leaf in grid.tree().leaves() {
            let uni = leaf.attribute_array("uni").unwrap();
            assert!(uni.is_uniform());
            assert_eq!(uni.get::<f32>(0), 3.5);
            let hid = leaf.attribute_array("hid").unwrap();
            assert!(hid.is_hidden() && hid.is_uniform());
            assert_eq!(hid.get::<i32>(0), 7);
            assert!(!leaf.has_attribute("tmp"), "transient attributes are not written");
            leaf.validate_offsets().unwrap();
        }
        assert_eq!(group_point_count(grid.tree(), "even"), 20);
        assert_eq!(group_point_count(grid.tree(), "first"), 5);
        assert_eq!(group_point_count(grid.tree(), "unused"), 0);
    }
}

#[test]
fn codecs_from_cpp() {
    for (grid_name, tol) in [("fxpt16", 0.25 / 65535.0 + 1e-6), ("fxpt8", 0.25 / 255.0 + 1e-6), ("trnc", 1e-3)] {
        let grid = read_points("points_codecs", grid_name);
        let ws = grid.world_positions().unwrap();
        assert_eq!(ws.len(), N);
        for k in 0..N {
            let p = position(k);
            let p = Vec3d::new(p[0] as f64, p[1] as f64, p[2] as f64);
            assert!(ws.iter().any(|q| (*q - p).abs().max_component() <= tol), "{} point {}", grid_name, k);
        }
    }
    let grid = read_points("points_codecs", "fxpt16");
    for leaf in grid.tree().leaves() {
        let n = leaf.attribute_handle::<Vec3f>("N").unwrap();
        let alpha = leaf.attribute_handle::<f32>("alpha").unwrap();
        let h = leaf.attribute_handle::<f32>("h").unwrap();
        let col = leaf.attribute_handle::<Vec3f>("col").unwrap();
        for i in leaf.index_on() {
            let f = i as f32 / 10.0;
            assert!((n.get(i) - Vec3f::new(1.0, f, -0.5).unit()).length() < 0.05);
            assert!((alpha.get(i) - (f * 0.5).min(1.0)).abs() <= 1.0 / 255.0);
            assert!((h.get(i) - (1.0 + f)).abs() <= 2e-3);
            let c = Vec3f::new(f.min(1.0), 0.5, (1.0 - f * 0.5).clamp(0.0, 1.0));
            assert!((col.get(i) - c).abs().max_component() <= 1.0 / 65535.0 + 1e-6);
        }
    }
}

#[test]
fn misc_grids_from_cpp() {
    let (_, grids) = io::read_file(ref_path("points_misc")).unwrap();
    let empty = grids.iter().find(|g| g.name() == "empty").unwrap().as_point_data().unwrap();
    assert_eq!(point_count(empty.tree()), 0);
    assert!(empty.tree().is_empty());
    let inactive = grids.iter().find(|g| g.name() == "inactive").unwrap().as_point_data().unwrap();
    assert_eq!(point_count(inactive.tree()), N as u64);
    assert_eq!(inactive.tree().active_voxel_count(), 39);
    let off = inactive_point_count(inactive.tree());
    assert!(off >= 1);
    assert_eq!(active_point_count(inactive.tree()) + off, N as u64);
}

// ---------------------------------------------------------------------------
// Writing

fn all_options() -> Vec<WriteOptions> {
    [
        Compression::NONE,
        Compression::ACTIVE_MASK,
        Compression::ZIP | Compression::ACTIVE_MASK,
        Compression::BLOSC | Compression::ACTIVE_MASK,
        Compression::BLOSC,
    ]
    .into_iter()
    .map(WriteOptions::with_compression)
    .collect()
}

/// Rewriting the reference files with every compression preserves their content.
#[test]
fn rewrite_reference_files() {
    let dir = scratch_dir("points_rewrite");
    for name in REFERENCE_FILES {
        let (meta, grids) = io::read_file(ref_path(name)).unwrap();
        let expected = std::fs::read_to_string(data("points").join(format!("{}.dump.txt", name))).unwrap();
        for (k, opts) in all_options().iter().enumerate() {
            let out = dir.join(format!("{}_{}.vdb", name, k));
            io::write_file_with_options(&out, &grids, &meta, opts).unwrap();
            assert_same_dump(&dump_points_file(&out), &expected, &format!("{} with {:?}", name, opts.compression));
        }
    }
}

/// Point grids built in Rust with several codecs, attributes, strings and groups.
fn rust_grids(large: bool) -> Vec<AnyGrid> {
    let n = if large { 200_000 } else { 3000 };
    let pos: Vec<Vec3f> = (0..n)
        .map(|i| {
            let f = i as f32;
            Vec3f::new((f * 0.618).sin() * 20.0, (f * 0.377).cos() * 15.0 - 3.0, (f * 0.0013).fract() * 40.0 - 20.0)
        })
        .collect();
    let mut out = Vec::new();
    let transform = Transform::linear(0.5);
    let index = vdb::tools::point_index_grid::create_point_index_grid(&pos, &transform);
    for (k, codec) in
        [Codec::Null, Codec::FIXED_POINT_16, Codec::FIXED_POINT_8, Codec::Truncate].into_iter().enumerate()
    {
        let mut grid = create_point_data_grid_from_index(&index, &pos, codec, &transform, None).unwrap();
        grid.set_name(&format!("rust_{}", codec));
        if k == 0 || k == 1 {
            let tree = grid.tree_mut();
            let ids: Vec<i32> = (0..n as i32).collect();
            append_typed_attribute(tree, "id", Codec::Null, 0i32, 1, None, false, false).unwrap();
            populate_attribute(tree, index.tree(), "id", &ids, 1).unwrap();
            let normals: Vec<Vec3f> = pos.iter().map(|p| p.unit()).collect();
            append_typed_attribute(tree, "N", Codec::UnitVec, Vec3f::zero(), 1, None, false, false).unwrap();
            populate_attribute(tree, index.tree(), "N", &normals, 1).unwrap();
            let names: Vec<String> = (0..n).map(|i| format!("s{}", i % 17)).collect();
            append_string_attribute(tree, "name", "", 1).unwrap();
            populate_string_attribute(tree, index.tree(), "name", &names, 1).unwrap();
            append_typed_attribute(tree, "uni", Codec::Null, 2.5f32, 1, Some(1.0f32), false, false).unwrap();
            append_typed_attribute(tree, "pair", Codec::Truncate, 0.0f32, 2, None, true, false).unwrap();
            append_typed_attribute(tree, "tmp", Codec::Null, 1.0f32, 1, None, false, true).unwrap();
            append_group(tree, "half").unwrap();
            let membership: Vec<i16> = (0..n).map(|i| (i % 2) as i16).collect();
            set_group(tree, index.tree(), &membership, "half", false).unwrap();
            append_group(tree, "all").unwrap();
            set_group_all(tree, "all", true).unwrap();
        }
        out.push(AnyGrid::PointData(grid));
    }
    out.push(AnyGrid::PointData(PointDataGrid::new().with_name("rust_empty")));
    out
}

#[test]
fn rust_written_files_roundtrip() {
    let dir = scratch_dir("points_roundtrip");
    let grids = rust_grids(false);
    let mut expected = String::new();
    let mut sorted: Vec<&AnyGrid> = grids.iter().collect();
    sorted.sort_by(|a, b| a.name().cmp(b.name()));
    for g in sorted {
        let mut p = g.as_point_data().unwrap().clone();
        // Transient attributes are not written.
        if p.tree().descriptor().is_some_and(|d| d.position("tmp").is_some()) {
            drop_attribute(p.tree_mut(), "tmp").unwrap();
        }
        dump_point_grid(&mut expected, g.name(), &p);
    }
    for (k, opts) in all_options().iter().enumerate() {
        let path = dir.join(format!("rust_{}.vdb", k));
        io::write_file_with_options(&path, &grids, &MetaMap::new(), opts).unwrap();
        assert_same_dump(&dump_points_file(&path), &expected, &format!("rust_{}", k));
        // A stream reads back identically too.
        let mut buf = Vec::new();
        io::write_stream(&mut buf, &grids, &MetaMap::new(), opts).unwrap();
        let (_, back) = io::read_stream(&buf[..]).unwrap();
        assert_eq!(back.len(), grids.len());
    }
    // Extracting attributes after a round trip gives the inputs back.
    let path = dir.join("rust_0.vdb");
    let grid = io::read_grid(&path, "rust_null").unwrap().into_point_data().unwrap();
    let (offsets, total) = point_offsets(grid.tree(), &NullFilter);
    let mut ids = vec![0i32; total as usize];
    convert_point_data_grid_attribute(&mut ids, grid.tree(), &offsets, 0, 1, 1, &NullFilter).unwrap();
    ids.sort_unstable();
    assert_eq!(ids, (0..3000).collect::<Vec<i32>>());
    assert_eq!(group_point_count(grid.tree(), "half"), 1500);
    assert_eq!(group_point_count(grid.tree(), "all"), 3000);
}

/// Canonical description of the point index grids of a file, as `points_ref dumpindex`
/// prints it.
fn dump_index_file(path: &Path) -> String {
    let (_, grids) = io::read_file(path).unwrap();
    let mut out = String::new();
    for g in grids.iter().filter_map(|g| g.as_point_index()) {
        writeln!(out, "grid {}", g.name()).unwrap();
        let m = g.transform().map().affine_matrix();
        out.push_str("  transform");
        for v in m.0.iter().flatten() {
            write!(out, " {}", hex(v.to_bits())).unwrap();
        }
        writeln!(out, "\n  leaf_count {}", g.tree().leaf_count()).unwrap();
        for leaf in g.tree().leaves() {
            let o = leaf.origin();
            let mut h = FNV_INIT;
            for v in leaf.leaf().buffer() {
                h = fnv(&v.to_le_bytes(), h);
            }
            write!(
                out,
                "  leaf {} {} {} on {} offsets {} indices",
                o[0],
                o[1],
                o[2],
                leaf.leaf().on_voxel_count(),
                hex(h)
            )
            .unwrap();
            for i in leaf.indices() {
                write!(out, " {}", i).unwrap();
            }
            out.push('\n');
        }
    }
    out
}

#[test]
fn point_index_grid_from_cpp() {
    let path = data("points").join("points_index.vdb");
    let expected = std::fs::read_to_string(data("points").join("points_index.dump.txt")).unwrap();
    assert_same_dump(&dump_index_file(&path), &expected, "points_index");
    let grid = io::read_grid(&path, "pindex").unwrap().into_point_index().unwrap();
    let pos: Vec<Vec3f> = (0..N).map(position).collect();
    assert!(vdb::tools::point_index_grid::is_valid_partition(&pos, &grid));
    // The same partition is built in Rust, and it round-trips through a file.
    let rust =
        vdb::tools::point_index_grid::create_point_index_grid(&pos, &Transform::linear(0.25)).with_name("pindex");
    let out = scratch_dir("points_index").join("index.vdb");
    io::write_file(&out, &[rust.into()], &MetaMap::new()).unwrap();
    assert_same_dump(&dump_index_file(&out), &expected, "rust points_index");
}

// ---------------------------------------------------------------------------
// C++ interoperability

/// Location of the C++ `points_ref` tool: `$POINTS_REF`, or tests/data/cpp/points_ref.
fn points_ref_binary() -> Option<std::path::PathBuf> {
    if let Some(p) = std::env::var_os("POINTS_REF") {
        return Some(std::path::PathBuf::from(p));
    }
    let p = data("cpp").join("points_ref");
    p.exists().then_some(p)
}

/// Write point grids with every compression option (including multi-page paged streams)
/// and check that the C++ library reads exactly what this crate reads. Requires the
/// `points_ref` tool (see tests/data/cpp/README.md): set `POINTS_REF` or build it as
/// tests/data/cpp/points_ref, then run `cargo test --test points -- --ignored`.
#[test]
#[ignore]
fn cpp_reads_rust_points() {
    let bin = points_ref_binary().expect("points_ref not found: set POINTS_REF or build tests/data/cpp/points_ref");
    let dir = scratch_dir("points_cpp_interop");
    let mut cases: Vec<(String, Vec<AnyGrid>)> =
        vec![("small".into(), rust_grids(false)), ("large".into(), rust_grids(true))];
    for name in REFERENCE_FILES {
        cases.push((format!("ref_{}", name), io::read_file(ref_path(name)).unwrap().1));
    }
    for (name, grids) in &cases {
        for (k, opts) in all_options().iter().enumerate() {
            let path = dir.join(format!("{}_{}.vdb", name, k));
            io::write_file_with_options(&path, grids, &MetaMap::new(), opts).unwrap();
            let out = std::process::Command::new(&bin).arg("dump").arg(&path).output().unwrap();
            assert!(out.status.success(), "{}: {}", name, String::from_utf8_lossy(&out.stderr));
            let cpp = String::from_utf8(out.stdout).unwrap();
            assert_same_dump(&dump_points_file(&path), &cpp, &format!("{}_{}", name, k));
        }
    }
    // Point index grids.
    let pos: Vec<Vec3f> =
        (0..5000).map(|i| Vec3f::new((i as f32 * 0.37).sin() * 9.0, (i % 97) as f32 * 0.1, 0.0)).collect();
    let index = vdb::tools::point_index_grid::create_point_index_grid(&pos, &Transform::linear(0.3)).with_name("idx");
    for (k, opts) in all_options().iter().enumerate() {
        let path = dir.join(format!("index_{}.vdb", k));
        io::write_file_with_options(&path, &[index.clone().into()], &MetaMap::new(), opts).unwrap();
        let out = std::process::Command::new(&bin).arg("dumpindex").arg(&path).output().unwrap();
        assert!(out.status.success(), "index: {}", String::from_utf8_lossy(&out.stderr));
        assert_same_dump(&dump_index_file(&path), &String::from_utf8(out.stdout).unwrap(), &format!("index_{}", k));
    }
}

/// The scatterers reproduce OpenVDB's random points bit for bit (points_scatter.vdb was
/// written by points_ref with the same parameters).
#[test]
fn scatter_matches_cpp() {
    let mut density = vdb::FloatGrid::new(0.0).with_transform(Transform::linear(0.5));
    density.tree_mut().fill(&vdb::CoordBBox::from_coords(0, 0, 0, 9, 9, 9), 0.5, true);
    density.set_value(&vdb::Coord::new(-20, 3, 5), 2.0);
    let mut uniform = uniform_point_scatter(&density, 300, 3, 0.5, Codec::Null).unwrap();
    uniform.set_name("uniform");
    let mut dense = dense_uniform_point_scatter(&density, 0.5, 1, 1.0, Codec::Null).unwrap();
    dense.set_name("dense");
    let mut non_uniform = non_uniform_point_scatter(&density, 4.0, 7, 0.8, Codec::Null).unwrap();
    non_uniform.set_name("nonuniform");
    let mut actual = String::new();
    for g in [&dense, &non_uniform, &uniform] {
        dump_point_grid(&mut actual, g.name(), g);
    }
    let expected = std::fs::read_to_string(data("points").join("points_scatter.dump.txt")).unwrap();
    assert_same_dump(&actual, &expected, "scatter");
}

/// Compare two level sets: same active voxels, values within `tol`.
fn assert_same_sdf(a: &vdb::FloatGrid, b: &vdb::FloatGrid, tol: f32, what: &str) {
    assert_eq!(a.active_voxel_count(), b.active_voxel_count(), "{}: active voxel count", what);
    assert_eq!(a.background(), b.background(), "{}: background", what);
    let acc = b.accessor();
    for (c, v) in a.tree().active_voxels() {
        let (w, on) = acc.probe_value(&c);
        assert!(on, "{}: voxel {:?} inactive", what, c);
        assert!((v - w).abs() <= tol, "{}: voxel {:?}: {} vs {}", what, c, v, w);
    }
}

/// Level sets rasterized from points match OpenVDB's (points_sdf.vdb was written by
/// points_ref from the points of points_attrs.vdb).
#[test]
fn rasterize_sdf_matches_cpp() {
    let (_, cpp) = io::read_file(data("points").join("points_sdf.vdb")).unwrap();
    let cpp = |name: &str| cpp.iter().find(|g| g.name() == name).unwrap().as_float().unwrap().clone();
    let pts = read_points("points_attrs", "attrs");
    let spheres = rasterize_spheres(&pts, 0.3, 2.0, None, &NullFilter).unwrap();
    assert_same_sdf(&spheres, &cpp("spheres"), 1e-6, "spheres");
    let varying = rasterize_spheres_varying(&pts, "density", 0.02, 2.0, None, &NullFilter).unwrap();
    assert_same_sdf(&varying, &cpp("spheres_varying"), 1e-6, "spheres_varying");
    let smooth = rasterize_smooth_spheres(&pts, 0.3, 0.6, 2.0, None, &NullFilter).unwrap();
    assert_same_sdf(&smooth, &cpp("smooth"), 1e-5, "smooth");
    let smooth_varying = rasterize_smooth_spheres_varying(&pts, "density", 0.02, 0.5, 2.0, None, &NullFilter).unwrap();
    assert_same_sdf(&smooth_varying, &cpp("smooth_varying"), 1e-5, "smooth_varying");
}

/// Trilinear rasterization matches OpenVDB's (`rasterizeTrilinear`).
#[test]
fn rasterize_trilinear_matches_cpp() {
    let (_, cpp) = io::read_file(data("points").join("points_sdf.vdb")).unwrap();
    let pts = read_points("points_attrs", "attrs");
    let cell = rasterize_trilinear::<f32, _>(pts.tree(), "density", &NullFilter).unwrap();
    let expected = cpp.iter().find(|g| g.name() == "trilinear").unwrap().as_float().unwrap();
    assert_eq!(cell.active_voxel_count(), expected.active_voxel_count());
    for (c, v) in cell.active_voxels() {
        let w = expected.get_value(&c);
        assert!((v - w).abs() <= 1e-5 * w.abs().max(1.0), "{:?}: {} vs {}", c, v, w);
    }
    let staggered = rasterize_trilinear_staggered::<Vec3f, _>(pts.tree(), "v", &NullFilter).unwrap();
    let expected = cpp.iter().find(|g| g.name() == "staggered").unwrap().as_vec3s().unwrap();
    assert_eq!(staggered.active_voxel_count(), expected.active_voxel_count());
    for (c, v) in staggered.active_voxels() {
        let w = expected.get_value(&c);
        assert!((v - w).abs().max_component() <= 1e-5 * w.abs().max_component().max(1.0), "{:?}", c);
    }
}

#[test]
fn point_count_and_mask_grids() {
    let grid = read_points("points_attrs", "attrs");
    let counts = point_count_grid::<i32, _>(&grid, &NullFilter);
    let total: i64 = counts.tree().active_voxels().map(|(_, v)| v as i64).sum();
    assert_eq!(total, N as i64);
    let even = GroupFilter::new("even", grid.tree().descriptor().unwrap()).unwrap();
    let counts = point_count_grid::<i32, _>(&grid, &even);
    let total: i64 = counts.tree().active_voxels().map(|(_, v)| v as i64).sum();
    assert_eq!(total, 20);
    let mask = convert_points_to_mask(&grid, &NullFilter);
    assert_eq!(mask.active_voxel_count(), grid.tree().active_voxel_count());
    let coarse = Transform::linear(1.0);
    let mask = convert_points_to_mask_transformed(&grid, &coarse, &NullFilter);
    assert!(mask.active_voxel_count() > 0 && mask.active_voxel_count() <= N as u64);
    let counts = point_count_grid_transformed::<i32, _>(&grid, &coarse, &NullFilter);
    let total: i64 = counts.tree().active_voxels().map(|(_, v)| v as i64).sum();
    assert_eq!(total, N as i64);
    let _ = points::point_count_filtered(grid.tree(), &even);
}
